      | undefined
    if (!response.ok || !payload?.data) {
      throw new ServerBackupError(payload?.error?.message ?? 'The server could not complete the restore request.', payload?.error?.code ?? 'REQUEST_FAILED')
    }
    return payload.data
  }
}

